#!/bin/bash
set -u
usage() { printf 'usage: report.sh --input DIR --out FILE\n' >&2; exit 2; }
input=''; out=''
while [ "$#" -gt 0 ]; do
  case $1 in
    --input) input=${2:-}; shift 2 ;;
    --out) out=${2:-}; shift 2 ;;
    --help) usage ;;
    *) usage ;;
  esac
done
[[ -d "$input" && -r "$input" ]] || usage
outdir=$(dirname -- "$out")
[[ -d "$outdir" && -w "$outdir" ]] || { printf 'cannot write to %s\n' "$outdir" >&2; exit 1; }
tmp=$(mktemp -- "$outdir/.report.XXXXXX") || exit 1
trap 'rm -f -- "$tmp"' EXIT
shopt -s nullglob
